## 2. grammar/dna-lang.grammar

```ebnf
grammar dna::}{::lang

<program>      ::= <organism>* ;

<organism>     ::= "organism" IDENT "{" <body> "}" ;
<body>         ::= (<field> | <gene> | <evolve> | <collapse>)* ;

<field>        ::= "field" IDENT ":" IDENT ;
<gene>         ::= "gene" IDENT "{" <gene_body> "}" ;
<gene_body>    ::= <expr>* ;

<expr>         ::= "emit" STRING
                 | "bifurcate" IDENT
                 | "sovereign"
                 | IDENT "(" <expr_list>? ")"
                 | IDENT ;

<expr_list>    ::= <expr> ("," <expr>)* ;

<evolve>       ::= "evolve" "{" <ode>* "}" ;
<ode>          ::= "∂τ" <state_tuple> "=" <rhs> ;
<state_tuple>  ::= "(" IDENT ("," IDENT)* ")" ;
<rhs>          ::= IDENT "(" <expr_list>? ")" ;

<collapse>     ::= "collapse" "{" <collapse_rule>* "}" ;
<collapse_rule>::= "if" <cond> IDENT ;
<cond>         ::= IDENT "<=" IDENT
                 | IDENT "→" NUMBER ;
```

---

## 3. grammar/7dcrsm-lang.grammar

```ebnf
grammar 7dCRSM::}{::lang

<manifold>     ::= "manifold" IDENT "{" <m_body> "}" ;
<m_body>       ::= <state> <hamiltonian> <constraint>* ;

<state>        ::= "state" IDENT "=" "(" IDENT ("," IDENT)* ")" ;
<hamiltonian>  ::= "law" IDENT ":" <h_terms> ;
<h_terms>      ::= <term> ( <term> )* ;
<term>         ::= IDENT IDENT
                 | "-" IDENT
                 | "+" IDENT IDENT ;

<constraint>   ::= "constraint:" <integral> ;
<integral>     ::= "∫" IDENT IDENT IDENT "=" NUMBER ;

<operator>     ::= "operator" IDENT ;
```

